function render_terms_modal(array $user): void
{
    $required = !user_has_accepted_current_terms($user);
    $acceptedAt = trim((string)($user['terms_accepted_at'] ?? ''));
    ?>
    <section class="terms-modal-backdrop<?= $required ? ' is-required' : ' is-hidden' ?>" data-terms-modal data-terms-required="<?= $required ? '1' : '0' ?>" role="dialog" aria-modal="true" aria-labelledby="terms-modal-title">
        <article class="terms-modal">
            <header class="terms-modal-header">
                <div><span>LigFlow</span><h2 id="terms-modal-title">Termos de Uso e Política de Privacidade</h2><p><?= $required ? 'Leia o documento e confirme o aceite para continuar utilizando a plataforma.' : 'Consulte novamente os termos vigentes para uso do LigFlow.' ?></p></div>
                <?php if (!$required): ?><button class="icon-button" type="button" data-close-terms aria-label="Fechar termos">x</button><?php endif; ?>
            </header>
            <div class="terms-modal-content" tabindex="0">
                <?php render_terms_content(); ?>
            </div>
            <footer class="terms-modal-footer">
                <?php if ($required): ?>
                    <form method="post" class="terms-acceptance-form">
                        <input type="hidden" name="action" value="accept_terms">
                        <input type="hidden" name="terms_version" value="<?= h(TERMS_VERSION) ?>">
                        <label class="check"><input type="checkbox" name="terms_acceptance" value="1" required data-terms-checkbox> Li e aceito os Termos de Uso e a Política de Privacidade do LigFlow.</label>
                        <button class="button" type="submit" disabled data-accept-terms>Continuar</button>
                    </form>
                <?php else: ?>
                    <small>Versão <?= h(TERMS_VERSION) ?><?= $acceptedAt !== '' ? ' - aceita em ' . h(datetime_utc_display($acceptedAt)) : '' ?></small>
                    <button class="button secondary" type="button" data-close-terms>Fechar</button>
                <?php endif; ?>
            </footer>
        </article>
    </section>
    <?php
}
